window.VanguardaAudit=(()=>{
 const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let generation=0;
 const fieldLabels={projectId:'Projeto',propertyId:'Imóvel',due:'Prazo de revisão',action:'Descrição da ação',owner:'Responsável pela revisão',progress:'Execução do cenário (%)',spent:'Despesas do cenário (R$ milhões)'};
 const value=v=>v===null||v===undefined?'Não registrado':typeof v==='number'?v.toLocaleString('pt-BR'):String(v);
 function changes(event){return `<div class="table-scroll" role="region" tabindex="0" aria-label="Campos alterados"><table class="history-fields"><caption class="sr-only">Valores anteriores e novos</caption><thead><tr><th>Campo</th><th>Anterior</th><th>Novo</th></tr></thead><tbody>${(event.changedFields||[]).map(field=>`<tr><th scope="row">${esc(fieldLabels[field]||field)}</th><td>${esc(value(event.before?.[field]))}</td><td>${esc(value(event.after?.[field]))}</td></tr>`).join('')||'<tr><td colspan="3">Sem alteração de campos registrada.</td></tr>'}</tbody></table></div>`;}
 async function projectHistory(container,projectId){
  let page=1,run=0;
  async function load(){const current=++run;container.innerHTML='<p role="status">Carregando histórico do servidor…</p>';
   try{const response=await fetch('/api/projects/'+encodeURIComponent(projectId)+'/history?page='+page,{cache:'no-store'});if(!response.ok)throw Error(response.status===401||response.status===403?'Sessão ausente ou sem permissão para consultar o histórico.':'Não foi possível consultar o histórico.');const data=await response.json();if(current!==run||!container.isConnected)return;
    container.innerHTML=`<p class="subtitle">${data.mode==='demo'?'Operações persistidas do protótipo; identidade não verificada.':'Registros persistidos no servidor.'} ${data.scope==='own'?'Você vê somente as ações da sua conta.':'Você vê as ações registradas neste projeto.'} A base sintética não possui histórico de edição.</p><p class="subtitle">Dados pessoais e descrição da ação permanecem mascarados conforme a política do log.</p>${data.events.map(event=>`<article class="history-event"><div class="card-head"><b>${esc(event.user.name)}</b><time datetime="${esc(event.timestamp)}">${esc(new Date(event.timestamp).toLocaleString('pt-BR',{timeZone:'America/Sao_Paulo'}))} · Brasília</time></div><p>${esc(event.action)} · Ações PMO</p>${changes(event)}<p class="subtitle">Justificativa: ${esc(event.justification||'Não registrada.')}</p></article>`).join('')||'<p>Nenhuma alteração registrada neste escopo. Eventos antigos sem diário não são recriados.</p>'}<div class="history-pagination"><button class="button" data-history-prev ${page===1?'disabled':''}>Anterior</button><span>${data.total} eventos · página ${page} de ${Math.max(1,Math.ceil(data.total/data.pageSize))}</span><button class="button" data-history-next ${page*data.pageSize>=data.total?'disabled':''}>Próxima</button></div>`;
    container.querySelector('[data-history-prev]').onclick=()=>{page--;load();};container.querySelector('[data-history-next]').onclick=()=>{page++;load();};
   }catch(error){if(current!==run||!container.isConnected)return;container.innerHTML=`<p role="alert">${esc(error.message)}</p><button class="button" data-history-retry>Tentar novamente</button>`;container.querySelector('[data-history-retry]').onclick=load;}
  }
  await load();
 }

 function render(){const main=document.querySelector('#main');main.innerHTML='<div class="eyebrow">Administração</div><h1>Auditoria</h1><p id="audit-mode" class="notice"></p><form id="audit-filters" class="filters filter-bar"><label>Busca<input type="search" name="q"></label><label>Usuário<input name="user" placeholder="Nome ou identificador"></label><label>De (UTC)<input type="datetime-local" name="from"></label><label>Até (UTC)<input type="datetime-local" name="to"></label><label>Ação<select name="action"><option value="">Todas</option><option>adição</option><option>alteração</option><option>exclusão</option></select></label><label>Módulo<select name="module"><option value="">Todos</option><option>Ações PMO</option><option>Interesses</option><option>Autenticação</option></select></label><label>Resultado<select name="result"><option value="">Todos</option><option>concluído</option><option>falhou</option></select></label><button class="button primary" type="submit">Filtrar</button></form><div id="audit-content" aria-live="polite"></div>';let page=1;const form=main.querySelector('form');
 async function load(){const run=++generation,content=document.querySelector('#audit-content');if(!content)return;content.innerHTML='<p role="status">Carregando eventos…</p>';try{const params=new URLSearchParams(new FormData(form));for(const k of ['from','to'])if(params.get(k))params.set(k,new Date(params.get(k)+'Z').toISOString());params.set('page',page);const response=await fetch('/api/audit?'+params,{cache:'no-store'});if(response.status===400){const error=await response.json();throw Error(error.error||'Filtros inválidos.');}if(!response.ok)throw Error(response.status===403?'Consulta permitida somente a administradores autorizados.':response.status===401?'Sessão expirada. Entre novamente.':'Não foi possível consultar o log.');const data=await response.json();if(run!==generation||!content.isConnected)return;document.querySelector('#audit-mode').textContent=data.mode==='demo'?'Demonstração: operações reais do protótipo, sem identidade corporativa verificada. Não é auditoria de produção.':'Auditoria do servidor. Horários apresentados em UTC (UTC+00:00).';content.innerHTML=`<p>${data.total} eventos · mais recentes primeiro · UTC+00:00</p><div class="card audit-table"><div class="table-scroll" role="region" aria-label="Eventos de auditoria; tabela rolável" tabindex="0"><table><caption>Auditoria — eventos persistidos no servidor</caption><thead><tr><th>Data/hora (UTC+00:00)</th><th>Usuário</th><th>Ação</th><th>Módulo</th><th>Registro</th><th>Resultado / detalhes</th></tr></thead><tbody>${data.events.map(e=>`<tr><td><time datetime="${esc(e.timestamp)}">${esc(new Date(e.timestamp).toISOString().replace('T',' ').replace('Z',' UTC'))}</time></td><td>${esc(e.user.name)}<small>${esc(e.user.id)}</small></td><td>${esc(e.action)}</td><td>${esc(e.module)}</td><td>${esc(e.recordId)}</td><td><span class="status ${e.result==='falhou'?'Critico':''}">${esc(e.result)}</span><details><summary>Antes / Depois</summary><p>${esc(e.description)}</p><small>Evento: ${esc(e.id)}</small>${changes(e)}<p>Justificativa: ${esc(e.justification||'Não registrada.')}</p></details></td></tr>`).join('')||'<tr><td colspan="6">Nenhum evento para estes filtros. Operações antigas sem histórico não são recriadas.</td></tr>'}</tbody></table></div></div><div class="audit-pagination"><button class="button" id="audit-prev" ${page===1?'disabled':''}>Anterior</button><span>Página ${page} de ${Math.max(1,Math.ceil(data.total/data.pageSize))}</span><button class="button" id="audit-next" ${page*data.pageSize>=data.total?'disabled':''}>Próxima</button></div>`;document.querySelector('#audit-prev').onclick=()=>{page--;load();};document.querySelector('#audit-next').onclick=()=>{page++;load();};}catch(e){if(run===generation&&content.isConnected){content.innerHTML=`<p role="alert">${esc(e.message)}</p><button class="button" id="audit-retry">Tentar novamente</button>`;document.querySelector('#audit-retry').onclick=load;}}}
 form.onsubmit=e=>{e.preventDefault();page=1;load();};load();}
 return {render,projectHistory};
})();
